import json, subprocess, sys, copy
MAIN=['python3','-I','/workspace/submission/main.py']
def run_raw(raw):
    p=subprocess.run(MAIN,input=raw,capture_output=True)
    return p.returncode,p.stdout,p.stderr
def expect_invalid(label,obj=None,raw=None):
    if raw is None: raw=json.dumps(obj).encode()
    rc,out,err=run_raw(raw)
    ok = rc==0 and json.loads(out)=={"error":"invalid-input"}
    if not ok:
        print("FAIL invalid",label,rc,out[:200],err[:200])
    return ok
def expect_valid(label,obj):
    raw=json.dumps(obj).encode()
    rc,out,err=run_raw(raw)
    try:
        d=json.loads(out)
        ok= rc==0 and 'error' not in d and set(d)=={'runs','audits','diagnostic'}
    except Exception:
        ok=False; d=None
    if not ok:
        print("FAIL valid",label,rc,out[:500],err[:200])
    return ok

base={"zones":[],"profiles":[{"id":"p","max_aliases":0,"cname":"follow","wildcard":"rfc"}],"queries":[],"observations":[]}
fails=0
# root
for obj in [None, [], 5, {}, {"zones":[],"profiles":[],"queries":[],"observations":[]}]:
    fails += not expect_invalid("root",obj)
# duplicate key raw
for raw in [b'{"zones":[],"zones":[],"profiles":[],"queries":[],"observations":[]}', b'{"zones":[],"profiles":[{"id":"p","id":"q","max_aliases":0,"cname":"follow","wildcard":"rfc"}],"queries":[],"observations":[]}']:
    fails += not expect_invalid("dupkey",raw=raw)
# bad utf8 / bad json / nonfinite
for raw in [b'\xff', b'{', b'{"zones":[],"profiles":[{"id":"p","max_aliases":NaN,"cname":"follow","wildcard":"rfc"}],"queries":[],"observations":[]}', b'{"zones":[],"profiles":[{"id":"p","max_aliases":1e999,"cname":"follow","wildcard":"rfc"}],"queries":[],"observations":[]}']:
    fails += not expect_invalid("parse",raw=raw)
# too deep
deep=b'['*33+b']'*33
fails += not expect_invalid("deep",raw=b'{"zones":[],"profiles":[{"id":"p","max_aliases":0,"cname":"follow","wildcard":"rfc"}],"queries":[],"observations":[],"observations":[]}')
raw=b'{"zones":'+deep+b',"profiles":[{"id":"p","max_aliases":0,"cname":"follow","wildcard":"rfc"}],"queries":[],"observations":[]}'
fails += not expect_invalid("deep2",raw=raw)

def mk(**kw):
    o=copy.deepcopy(base)
    o.update(kw); return o
# profile invalid variants
for pid in ["", "a"*33, "a.b", "é", 1, None, True]:
    p={"id":pid,"max_aliases":0,"cname":"follow","wildcard":"rfc"}
    fails += not expect_invalid("pid %r"%pid,mk(profiles=[p]))
for ma in [True,False,-1,65,1.0,"0",None]:
    p={"id":"p","max_aliases":ma,"cname":"follow","wildcard":"rfc"}
    fails += not expect_invalid("ma %r"%ma,mk(profiles=[p]))
for c in ["x",True,None]:
    p={"id":"p","max_aliases":0,"cname":c,"wildcard":"rfc"}
    fails += not expect_invalid("cname %r"%c,mk(profiles=[p]))
for w in ["x",True,None]:
    p={"id":"p","max_aliases":0,"cname":"follow","wildcard":w}
    fails += not expect_invalid("wild %r"%w,mk(profiles=[p]))
# extra keys
p={"id":"p","max_aliases":0,"cname":"follow","wildcard":"rfc","x":1}
fails += not expect_invalid("extra profile",mk(profiles=[p]))
# names
for n in ["", "a", "A..B.", "a..b.", ".a.", "a"*64+".", "a b.", "*.", "a.*b.", "-.","_.", "a.b", "é.", "a\u0000."]:
    q={"id":"q","name":n,"type":"A","cost":1}
    fails += not expect_invalid("name %r"%n,mk(queries=[q]))
# valid names
for n in [".", "*.", "a.b.", "a"*63+".", "A-B_C.", "a.*.b."]:
    q={"id":"q","name":n,"type":"A","cost":1}
    if not expect_valid("valid name %r"%n,mk(queries=[q])):
        fails+=1
# query types/cost
for t in ["a","ANY",True,None,"A "]:
    q={"id":"q","name":"a.","type":t,"cost":1}
    fails += not expect_invalid("qtype %r"%t,mk(queries=[q]))
for c in [0,1001,True,1.0,"1",None]:
    q={"id":"q","name":"a.","type":"A","cost":c}
    fails += not expect_invalid("qcost %r"%c,mk(queries=[q]))
# record data
def rec(owner="a.",typ="A",data="1.2.3.4"):
    return {"owner":owner,"type":typ,"data":data}
zone=lambda *rs: [{"origin":".","records":list(rs)}]
for typ,data in [("A","1.2.3"),("A","1.2.3.256"),("A","01.2.3.4"),("A","1.2.3.-1"),("A","1.2.3.4.5"),("A","+1.2.3.4"),("A","1.2.3.4 "),
                 ("TXT","x"*257),("TXT","\x1f"),("TXT","\x7f"),("TXT","é"),
                 ("AAAA","::1%eth0"),("AAAA","1.2.3.4"),("AAAA","gg::1"),("CNAME","relative"),("CNAME","a..b."),("A",""),("A",None),("A",1)]:
    fails += not expect_invalid("data %r %r"%(typ,data),mk(zones=zone(rec(typ=typ,data=data))))
# valid data
for typ,data in [("A","0.0.0.0"),("TXT","" ),("TXT","x"*256),("AAAA","::FFFF:192.0.2.1"),("CNAME","X.Y."),("TXT"," ~\\\"")]:
    if not expect_valid("valid data %r"%data,mk(zones=zone(rec(typ=typ,data=data)))): fails+=1
# zones: owner outside, cname at origin, cname coexist, multi target, duplicate origins, 65 distinct
fails += not expect_invalid("outside",mk(zones=[{"origin":"test.","records":[rec(owner="x.other.")]}]))
fails += not expect_invalid("cname origin",mk(zones=[{"origin":".","records":[rec(owner=".",typ="CNAME",data="b.")]}]))
fails += not expect_invalid("cname coexist",mk(zones=[{"origin":".","records":[rec(owner="a.",typ="CNAME",data="b."),rec(owner="a.",typ="A",data="1.2.3.4")]}]))
fails += not expect_invalid("cname 2 targets",mk(zones=[{"origin":".","records":[rec(owner="a.",typ="CNAME",data="b."),rec(owner="a.",typ="CNAME",data="c.")]}]))
fails += not expect_invalid("dup origin",mk(zones=[{"origin":"Test.","records":[]},{"origin":"test.","records":[]}]))
many=[rec(owner="a.",typ="A",data="1.2.3.%d"%i) for i in range(65)]
fails += not expect_invalid("65 rrset",mk(zones=zone(*many)))
# duplicate allowing 65 entries => distinct 1 valid
many=[rec(owner="a.",typ="A",data="1.2.3.4") for i in range(65)]
if not expect_valid("65 dup entries",mk(zones=zone(*many))): fails+=1
# observations
obs=lambda result: [{"id":"o","query":"q","profile":"p","result":result}]
q={"id":"q","name":"a.","type":"A","cost":1}
for res in [{"status":"timeout","x":1},{"status":"response","rcode":"NOERROR"},{"status":"response","rcode":"BAD","answer":[]},{"status":"response","rcode":"NOERROR","answer":[],"x":1},{"status":"x"},{}]:
    fails += not expect_invalid("obs %r"%res,mk(queries=[q],observations=obs(res)))
fails += not expect_invalid("obs ref",mk(queries=[q],observations=[{"id":"o","query":"z","profile":"p","result":{"status":"timeout"}}]))
# observed 129 records
ans=[rec() for _ in range(129)]
fails += not expect_invalid("obs 129",mk(queries=[q],observations=obs({"status":"response","rcode":"NOERROR","answer":ans})))
# valid observed unusual owners and duplicates
ans=[rec(owner="Out.Side.",data="10.0.0.1"),rec(owner="out.side.",data="10.0.0.1")]
if not expect_valid("obs ok",mk(queries=[q],observations=obs({"status":"response","rcode":"NOERROR","answer":ans}))): fails+=1
print("fails",fails)
